\label{lmm:ccsqrtprop}
	Let $\tau\in\mc S_0$.
	\begin{itemize}
		\item Then $\tau_{\!\sqrt{}}$ is nonnegative, nondecreasing, and concave.
		\item If $\tau_{\!\sqrt{}}$ is differentiable, then $\tau_{\!\sqrt{}}^\prime$ is nonnegative and nonincreasing.
		\item If $\tau_{\!\sqrt{}}$ is twice differentiable, then $\tau_{\!\sqrt{}}^{\prime\prime}$ is nonpositive.
	\end{itemize}

As $\tau$ is nonnegative, so is $\tau_{\!\sqrt{}}$.
We have 
\begin{align*}
	\tau_{\!\sqrt{}}^\prime(x) &= \frac{\tau^\prime(\sqrt{x})}{2 \sqrt{x}}\, ,\\
	\tau_{\!\sqrt{}}^{\prime\prime}(x) &= \frac{\tau^{\prime\prime}(\sqrt{x})-\frac{\tau^\prime(\sqrt{x})}{\sqrt{x}}}{4x}\, .
\end{align*}
As $\tau^\prime$ is nonnegative, so is $\tau_{\!\sqrt{}}^\prime$. Thus, $\tau$ is increasing.
Furthermore, as $\tau^{\prime\prime}$ is nonincreasing, 
\begin{equation}
	\tau^\prime(\sqrt{x}) - \tau^\prime(0) = \int_0^{\sqrt{x}} \tau^{\prime\prime}(u) \mathrm{d} u \geq \sqrt{x} \tau^{\prime\prime}(x) \, .
\end{equation}
Thus, with $\tau^\prime(0) \geq 0$, we obtain  $\tau^\prime(\sqrt{x}) \geq \sqrt{x} \tau^{\prime\prime}(x)$. Hence, $\tau_{\!\sqrt{}}^{\prime\prime}$ is nonpositive, $\tau_{\!\sqrt{}}^\prime$ is nonincreasing, and $\tau_{\!\sqrt{}}$ is concave.

